{"explanation":"The graph of y = tan(x) repeats every π and crosses the x-axis at integer multiples of π. Its vertical asymptotes are x = π/2 + kπ: at these values cos(x) = 0, so tan(x) is undefined. As x approaches an asymptote, the curve rises or falls without bound.","manimCode":"const pi = Math.PI;
const ax = new Axes({ xRange: [-2*pi, 2*pi, pi/2], yRange: [-3.3, 3.3, 1], xLength: 11.4, yLength: 5.1, tips: false });
const title = new Text({ text: 'y = tan(x)', color: WHITE, fontSize: 36 });
title.moveTo([0, 3.45, 0]);
scene.add(ax, title);

const asymptotes = [-3*pi/2, -pi/2, pi/2, 3*pi/2];
const names = ['−3π/2', '−π/2', 'π/2', '3π/2'];
for (let i = 0; i < asymptotes.length; i++) {
  const x = asymptotes[i];
  for (let y = -3.1; y < 3.1; y += 0.55) {
    const dash = new Polygon({ vertices: [ax.c2p(x, y), ax.c2p(x, Math.min(y + 0.28, 3.1))], color: RED });
    dash.setStrokeWidth(2);
    dash.setFillOpacity(0);
    scene.add(dash);
  }
  const label = new Text({ text: names[i], color: RED, fontSize: 21 });
  label.moveTo([ax.c2p(x, 0)[0], 2.8, 0]);
  scene.add(label);
}

const gap = 0.31;
const ends = [-2*pi, ...asymptotes, 2*pi];
for (let i = 0; i < ends.length - 1; i++) {
  const left = ends[i] + (i === 0 ? 0 : gap);
  const right = ends[i + 1] - (i === ends.length - 2 ? 0 : gap);
  const branch = ax.plot(x => Math.tan(x), { xRange: [left, right], color: BLUE_C, numSamples: 180 });
  await scene.play(new Create(branch));
}

const note = new Text({ text: 'Asymptotes: x = π/2 + kπ', color: RED, fontSize: 24 });
note.moveTo([-3.75, -3.32, 0]);
scene.add(note);

let xValue = 0;
const dot = new Dot({ point: ax.c2p(0, 0), color: YELLOW });
dot.addUpdater(d => d.moveTo(ax.c2p(xValue, Math.tan(xValue))));
scene.add(dot);
const controls = new Controls(scene, { position: 'bottom-right', width: 250 });
controls.addSlider({ label: 'Explore central branch', min: -1.25, max: 1.25, value: 0, step: 0.01, onChange: v => { xValue = v; } });
await scene.wait(999999);"}

